class KyrgyzInputMethodService :
    InputMethodService(),
    KyrgyzKeyboardEngine.Listener,
    LifecycleOwner,
    ViewModelStoreOwner,
    SavedStateRegistryOwner {

    private val lifecycleRegistry = LifecycleRegistry(this)
    private val store = ViewModelStore()
    private val savedStateController = SavedStateRegistryController.create(this)

    override val lifecycle: Lifecycle get() = lifecycleRegistry
    override val viewModelStore: ViewModelStore get() = store
    override val savedStateRegistry: SavedStateRegistry get() = savedStateController.savedStateRegistry

    private val engine: KyrgyzKeyboardEngine by lazy { KyrgyzKeyboardEngine(this) }

    // UI 状态，供 Compose 读取
    private var languageState by mutableStateOf(Language.KYRGYZ)
    private var layoutState by mutableStateOf(LayoutType.DEFAULT)
    private var shiftState by mutableStateOf(false)
    private var composingState by mutableStateOf("")
    private var candidatesState by mutableStateOf<List<String>>(emptyList())

    override fun onCreate() {
        super.onCreate()
        savedStateController.performRestore(null)
        lifecycleRegistry.currentState = Lifecycle.State.CREATED
        // 预热
        KyrgyzKeyboardLayouts.forType(LayoutType.SYMBOL)
        KyrgyzKeyboardLayouts.forType(LayoutType.DEFAULT)
        EnglishKeyboardLayouts.letterLayout(false)
        PinyinKeyboardLayouts.layout
        PinyinDictionary.query("ni") // 预热字典
    }

    override fun onCreateInputView(): View {
        lifecycleRegistry.currentState = Lifecycle.State.RESUMED
        window?.window?.decorView?.let { decor ->
            decor.setViewTreeLifecycleOwner(this)
            decor.setViewTreeViewModelStoreOwner(this)
            decor.setViewTreeSavedStateRegistryOwner(this)
        }
        val composeView = ComposeView(this)
        composeView.setViewTreeLifecycleOwner(this)
        composeView.setViewTreeViewModelStoreOwner(this)
        composeView.setViewTreeSavedStateRegistryOwner(this)
        composeView.setContent {
            KyrgyzKeyboardTheme {
                KeyboardRoot(
                    engine = engine,
                    language = languageState,
                    layout = layoutState,
                    shift = shiftState,
                    composing = composingState,
                    candidates = candidatesState,
                    onStateChanged = { syncStateFromEngine() }
                )
            }
        }
        return composeView
    }

    override fun onStartInputView(info: android.view.inputmethod.EditorInfo?, restarting: Boolean) {
        super.onStartInputView(info, restarting)
        syncStateFromEngine()
    }

    private fun syncStateFromEngine() {
        languageState = engine.currentLanguage
        layoutState = engine.currentLayout
        shiftState = engine.englishShift
        composingState = engine.composing
        candidatesState = engine.candidates
    }

    override fun onDestroy() {
        lifecycleRegistry.currentState = Lifecycle.State.DESTROYED
        store.clear()
        super.onDestroy()
    }

    // Engine 回调
    override fun onKeyPress(code: String) {
        currentInputConnection?.commitText(code, 1)
    }

    override fun onKeyAction(action: FunctionType) {
        val ic = currentInputConnection ?: return
        when (action) {
            FunctionType.SPACE -> ic.commitText(" ", 1)
            FunctionType.NEWLINE -> ic.commitText("\n", 1)
            FunctionType.BACKSPACE -> {
                val selected = ic.getSelectedText(0)
                if (!selected.isNullOrEmpty()) ic.commitText("", 1)
                else ic.deleteSurroundingText(1, 0)
            }
            FunctionType.DONE -> requestHideSelf(0)
            FunctionType.SWITCH_LAYOUT, FunctionType.SHIFT, FunctionType.SWITCH_LANGUAGE -> Unit
        }
    }

    override fun onComposingChanged(composing: String) {
        val ic = currentInputConnection ?: return
        if (composing.isEmpty()) {
            // 用空串替换 composing 区域，再 finish；仅 finishComposingText 会把 composing 固化为普通文本。
            ic.setComposingText("", 1)
            ic.finishComposingText()
        } else {
            ic.setComposingText(composing, 1)
        }
    }

    override fun onCommitCandidate(text: String) {
        val ic = currentInputConnection ?: return
        // commitText 在存在 composing 区域时会自动替换该区域，正好达成"用候选字替换拼音串"的效果。
        ic.commitText(text, 1)
    }
}

@Composable
private fun KeyboardRoot(
    engine: KyrgyzKeyboardEngine,
    language: Language,
    layout: LayoutType,
    shift: Boolean,
    composing: String,
    candidates: List<String>,
    onStateChanged: () -> Unit
) {
    val rows = remember(language, layout, shift) { engine.getRows() }
    val isRtl = language == Language.KYRGYZ
    val direction = if (isRtl) LayoutDirection.Rtl else LayoutDirection.Ltr

    CompositionLocalProvider(LocalLayoutDirection provides direction) {
        Surface(
            color = MaterialTheme.colorScheme.surface,
            modifier = Modifier.fillMaxWidth()
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(4.dp),
                verticalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                // 候选栏：仅拼音模式显示
                if (language == Language.PINYIN) {
                    CandidateBar(
                        composing = composing,
                        candidates = candidates,
                        onPick = { idx ->
                            engine.selectCandidate(idx)
                            onStateChanged()
                        }
                    )
                }
                val onKey: (KyrgyzKey) -> Unit = remember(engine, onStateChanged) {
                    { k ->
                        engine.handleKey(k)
                        onStateChanged()
                    }
                }
                val onVariant: (String) -> Unit = remember(engine, onStateChanged) {
                    { v ->
                        engine.handleVariant(v)
                        onStateChanged()
                    }
                }
                rows.forEachIndexed { rowIndex, row ->
                    key(language, layout, shift, rowIndex) {
                        KeyboardRowView(row = row, onKey = onKey, onVariant = onVariant)
                    }
                }
            }
        }
    }
}

@Composable
private fun CandidateBar(
    composing: String,
    candidates: List<String>,
    onPick: (Int) -> Unit
) {
    // 拼音栏保持 LTR，避免 RTL 环境下候选顺序反转
    CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Ltr) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(44.dp)
                .clip(RoundedCornerShape(6.dp))
                .background(MaterialTheme.colorScheme.surfaceVariant)
        ) {
            if (composing.isEmpty() && candidates.isEmpty()) {
                Text(
                    text = "中文拼音 · 键入拼音后此处显示候选",
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    fontSize = 13.sp,
                    modifier = Modifier
                        .padding(horizontal = 12.dp)
                        .align(Alignment.CenterStart)
                )
            } else {
                val scroll = rememberScrollState()
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .horizontalScroll(scroll)
                        .padding(horizontal = 8.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    if (composing.isNotEmpty()) {
                        Text(
                            text = composing,
                            color = MaterialTheme.colorScheme.primary,
                            fontSize = 14.sp,
                            modifier = Modifier
                                .padding(end = 12.dp)
                        )
                    }
                    candidates.forEachIndexed { i, cand ->
                        Box(
                            modifier = Modifier
                                .padding(horizontal = 4.dp)
                                .clip(RoundedCornerShape(4.dp))
                                .clickable { onPick(i) }
                                .padding(horizontal = 10.dp, vertical = 6.dp)
                        ) {
                            Text(
                                text = cand,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                fontSize = 20.sp
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun KeyboardRowView(
    row: KeyboardRow,
    onKey: (KyrgyzKey) -> Unit,
    onVariant: (String) -> Unit
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .height(52.dp),
        horizontalArrangement = Arrangement.spacedBy(4.dp)
    ) {
        row.keys.forEachIndexed { index, k ->
            key(index, k.code, k.function) {
                KeyView(
                    keyData = k,
                    modifier = Modifier.weight(k.weight),
                    onKey = onKey,
                    onVariant = onVariant
                )
            }
        }
    }
}

@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun KeyView(
    keyData: KyrgyzKey,
    modifier: Modifier = Modifier,
    onKey: (KyrgyzKey) -> Unit,
    onVariant: (String) -> Unit
) {
    val bg = when (keyData.type) {
        KeyType.FUNCTION -> MaterialTheme.colorScheme.secondaryContainer
        KeyType.SYMBOL -> MaterialTheme.colorScheme.surfaceVariant
        KeyType.LETTER -> MaterialTheme.colorScheme.primaryContainer
    }
    val fg = when (keyData.type) {
        KeyType.FUNCTION -> MaterialTheme.colorScheme.onSecondaryContainer
        KeyType.SYMBOL -> MaterialTheme.colorScheme.onSurfaceVariant
        KeyType.LETTER -> MaterialTheme.colorScheme.onPrimaryContainer
    }
    val hasVariants = keyData.variants.isNotEmpty()
    val clickModifier = if (hasVariants) {
        Modifier.combinedClickable(
            onClick = { onKey(keyData) },
            onLongClick = { keyData.variants.firstOrNull()?.let(onVariant) }
        )
    } else {
        Modifier.clickable { onKey(keyData) }
    }
    Box(
        modifier = modifier
            .clip(RoundedCornerShape(8.dp))
            .background(bg)
            .then(clickModifier),
        contentAlignment = Alignment.Center
    ) {
        Text(
            text = keyData.label,
            color = fg,
            fontSize = 20.sp,
            textAlign = TextAlign.Center
        )
    }
}